-- Схемы рынков без контейнеров (Геология, потом Дордой Моторс, Дордой): только чтобы найти рынок и сориентироваться
-- на нём. Ряды, проходы, входы, блоки — пиксели снимка, ось Y вниз; опорные GPS-точки лежат в той же схеме
-- (anchors), матрица GPS считается из них. Кудайберген — по-прежнему map_versions с контейнерами и маршрутами.
CREATE TABLE market_plans (
    market_id   BIGINT       PRIMARY KEY REFERENCES markets (id),
    version     INT          NOT NULL DEFAULT 1,
    -- формат снятия со спутника: boundary, rows, passages, entrances, blocks, pois, streets, labels, anchors
    data        JSONB        NOT NULL,
    updated_by  BIGINT       REFERENCES users (id) ON DELETE SET NULL,
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- has_map — у рынка есть карта (своя схема или схема с контейнерами); has_scheme — по-прежнему «контейнер из списка».
ALTER TABLE markets ADD COLUMN has_map BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE markets SET has_map = TRUE WHERE has_scheme;

-- Точки рынков (центр по OpenStreetMap): у Кудайбергена стояла точка в другом районе, у остальных не было.
UPDATE markets SET lat = 42.881512, lng = 74.523028 WHERE code = 'KUDAIBERGEN';
UPDATE markets SET lat = 42.886242, lng = 74.520709 WHERE code = 'GEOLOGIYA';
UPDATE markets SET lat = 42.872913, lng = 74.528546 WHERE code = 'DORDOI_MOTORS';
UPDATE markets SET lat = 42.938564, lng = 74.620484 WHERE code = 'DORDOI';

